import { test, expect, Page } from '@playwright/test';

test.describe('Clear All Filters Feature', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');

    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should display clear all filters button when filters are applied', async () => {
    // Apply first filter
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    // Apply second filter
    const priceFilter = page.getByRole('button', { name: /price/i });
    await priceFilter.click();

    const priceOption = page.getByRole('option', { name: /under \$100/i });
    await priceOption.click();

    // Verify clear all button is visible
    const clearAllButton = page.getByRole('button', { name: /clear all filters/i });
    await expect(clearAllButton).toBeVisible();
  });

  test('should clear all applied filters when clear all button is clicked', async () => {
    // Apply multiple filters
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    const priceFilter = page.getByRole('button', { name: /price/i });
    await priceFilter.click();

    const priceOption = page.getByRole('option', { name: /under \$100/i });
    await priceOption.click();

    const brandFilter = page.getByRole('button', { name: /brand/i });
    await brandFilter.click();

    const brandOption = page.getByRole('option', { name: /samsung/i });
    await brandOption.click();

    // Verify filters are applied
    const appliedFilters = page.getByRole('button', { name: /electronics|under \$100|samsung/i });
    const filterCount = await appliedFilters.count();
    expect(filterCount).toBeGreaterThan(0);

    // Click clear all button
    const clearAllButton = page.getByRole('button', { name: /clear all filters/i });
    await clearAllButton.click();

    // Verify all filters are cleared
    const clearedFilters = page.getByRole('button', { name: /electronics|under \$100|samsung/i });
    await expect(clearedFilters).toHaveCount(0);

    // Verify clear all button is hidden
    await expect(clearAllButton).not.toBeVisible();
  });

  test('should reset search results to default when all filters are cleared', async () => {
    // Apply a filter
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    // Get filtered results count
    const filteredResults = page.getByRole('article');
    const filteredCount = await filteredResults.count();

    // Clear all filters
    const clearAllButton = page.getByRole('button', { name: /clear all filters/i });
    await clearAllButton.click();

    // Wait for results to update
    await page.waitForLoadState('networkidle');

    // Get unfiltered results count
    const unfilteredResults = page.getByRole('article');
    const unfilteredCount = await unfilteredResults.count();

    // Verify results have changed
    expect(unfilteredCount).toBeGreaterThanOrEqual(filteredCount);
  });

  test('should disable clear all button when no filters are applied', async () => {
    // Verify clear all button is not visible initially
    const clearAllButton = page.getByRole('button', { name: /clear all filters/i });

    // Button should either not exist or be disabled
    const isVisible = await clearAllButton.isVisible().catch(() => false);
    const isDisabled = await clearAllButton.isDisabled().catch(() => false);

    expect(isVisible || isDisabled).toBe(true);
  });

  test('should maintain filter state before clearing and restore default state after clearing', async () => {
    // Apply filters with specific selections
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();

    const categoryOption = page.getByRole('option', { name: /electronics/i });
    await categoryOption.click();

    // Get initial filtered state
    const initialFilteredResults = page.getByRole('article');
    const initialCount = await initialFilteredResults.count();
    expect(initialCount).toBeGreaterThan(0);

    // Apply another filter
    const priceFilter = page.getByRole('button', { name: /price/i });
    await priceFilter.click();

    const priceOption = page.getByRole('option', { name: /under \$100/i });
    await priceOption.click();

    // Get double-filtered state
    const doubleFilteredResults = page.getByRole('article');
    const doubleFilteredCount = await doubleFilteredResults.count();
    expect(doubleFilteredCount).toBeLessThanOrEqual(initialCount);

    // Clear all filters
    const clearAllButton = page.getByRole('button', { name: /clear all filters/i });
    await clearAllButton.click();

    // Wait for results to update
    await page.waitForLoadState('networkidle');

    // Verify we're back to default state
    const defaultResults = page.getByRole('article');
    const defaultCount = await defaultResults.count();
    expect(defaultCount).toBeGreaterThanOrEqual(initialCount);

    // Verify no filter badges are visible
    const filterBadges = page.getByRole('button', { name: /electronics|under \$100/i });
    await expect(filterBadges).toHaveCount(0);
  });
});
